// The BSD checksum output is 5 digit integer
let bsd_width = 5;
let filename_bytes = os_str_as_bytes(filename.as_os_str())?;
let (pre, post) = match (options.algo_name, not_file) {
    (ALGORITHM_OPTIONS_SYSV, true) => (
        format!(
            "{} {}",
            sum.parse::<u16>().unwrap(),
            div_ceil(sz, options.output_bits)
        ),
        String::new(),
    ),
    (ALGORITHM_OPTIONS_SYSV, false) => (
        format!(
            "{} {} ",
            sum.parse::<u16>().unwrap(),
            div_ceil(sz, options.output_bits)
        ),
        String::new(),
    ),
    (ALGORITHM_OPTIONS_BSD, true) => (
        format!(
            "{:0bsd_width$} {:bsd_width$}",
            sum.parse::<u16>().unwrap(),
            div_ceil(sz, options.output_bits)
        ),
        String::new(),
    ),
    (ALGORITHM_OPTIONS_BSD, false) => (
        format!(
            "{:0bsd_width$} {:bsd_width$} ",
            sum.parse::<u16>().unwrap(),
            div_ceil(sz, options.output_bits)
        ),
        String::new(),
    ),
    (ALGORITHM_OPTIONS_CRC, true) => (format!("{sum} {sz}"), String::new()),
    (ALGORITHM_OPTIONS_CRC, false) => (format!("{sum} {sz} "), String::new()),
    (ALGORITHM_OPTIONS_BLAKE2B, _) if options.tag => {
        if let Some(length) = options.length {
            // Multiply by 8 here, as we want to print the length in bits.
            (
                format!("BLAKE2b-{} (", length * 8),
                format!(") = {sum}"),
            )
        } else {
            (format!("BLAKE2b ("), format!(") = {sum}"))
        }
    }
    _ => {
        if options.tag {
            (
                format!("{} (", options.algo_name.to_ascii_uppercase()),
                format!(") = {sum}"),
            )
        } else {
            let prefix = if options.asterisk { "*" } else { " " };
            (format!("{sum} {prefix}"), String::new())
        }
    }
};
let mut out = pre.into_bytes();
out.extend_from_slice(filename_bytes);
out.extend_from_slice(post.as_bytes());
out.push(b'\n');
stdout().write_all(&out)?;

